{"cards": [{"node_code": "N_90a7fd20c30ce5c2", "definition": "界定热力学系统边界、平衡态概念，定义压力、温度、体积等状态参数，并描述准静态、可逆等过程路径的基础理论分支。", "boundary": "聚焦于热力学分析的基本框架与概念定义。涵盖系统分类（开口/闭口）、状态公理、状态参数与过程函数的区别，以及过程路径的几何描述。与“纯物质”的区别在于：本节点侧重通用概念框架，不依赖特定工质；与“混合物”的区别在于：本节点处理单一相或简单系统，不涉及多组分相互作用。", "includes": ["热力学系统、边界、环境及平衡态定义", "状态参数（P, T, V, U, H, S等）与过程函数（Q, W）的区别", "准静态过程、可逆过程及过程路径在状态图上的表示"], "excludes": ["特定工质（如水、空气）的具体物性数据或状态方程（归入纯物质、状态方程与物性图表）", "多组分混合物的组成与相互作用性质（归入混合物、湿空气与溶液性质）"], "sibling_distinctions": [{"other_code": "N_6fa0308ea2b93dc2", "rule": "本节点定义通用的状态参数与过程概念；兄弟节点提供特定纯物质的状态方程及物性数据。"}, {"other_code": "N_9bd7ca56977d2031", "rule": "本节点处理单一组分或简单系统的状态描述；兄弟节点处理多组分混合物的组成、分压及混合规则。"}], "cross_boundary_rule": "涉及状态参数在特定工质上的应用时，若侧重概念定义与通用关系，主挂载至本节点；若侧重具体数值计算或图表读取，主挂载至“纯物质、状态方程与物性图表”。"}, {"node_code": "N_6fa0308ea2b93dc2", "definition": "研究单一组分纯物质的热力学性质，包括理想气体、实际气体状态方程，以及利用压焓图、温熵图等工具获取物性数据的方法。", "boundary": "聚焦于单一组分工质的状态方程与物性数据获取。涵盖理想气体模型、范德瓦尔斯等实际气体方程，以及水、制冷剂、蒸汽等常见工质的饱和线、临界点及相变特性。与“热力学系统”的区别在于：本节点侧重具体工质的数据与模型，而非通用概念；与“混合物”的区别在于：本节点仅处理单一组分，不涉及混合效应。", "includes": ["理想气体状态方程及实际气体修正（如压缩因子）", "纯物质相变特性、饱和线、临界点及超临界状态", "常用工质（水、蒸汽、制冷剂）的物性图表（压焓图、温熵图）应用"], "excludes": ["多组分混合物的组成计算与混合规则（归入混合物、湿空气与溶液性质）", "基于热力学定律的能量平衡与循环效率计算（归入热力学定律与可用能）"], "sibling_distinctions": [{"other_code": "N_90a7fd20c30ce5c2", "rule": "本节点提供特定纯物质的状态方程与物性数据；兄弟节点定义通用的状态参数与过程概念。"}, {"other_code": "N_9bd7ca56977d2031", "rule": "本节点处理单一组分物质的性质；兄弟节点处理由多种组分构成的混合物、湿空气及溶液的性质。"}], "cross_boundary_rule": "涉及工质物性数据时，若为单一组分（如纯水、纯氮气），主挂载至本节点；若涉及空气（视为混合物）或溶液，主挂载至“混合物、湿空气与溶液性质”。"}, {"node_code": "N_9bd7ca56977d2031", "definition": "研究多组分气体混合物、湿空气及液体溶液的热力学性质，包括分压定律、混合规则、湿度参数及相平衡关系。", "boundary": "聚焦于多组分系统的物性描述与计算。涵盖道尔顿分压定律、阿马格分体积定律、理想气体混合物的焓熵计算，以及湿空气的含湿量、相对湿度、露点等参数，和液体溶液的拉乌尔定律等。与“纯物质”的区别在于：本节点处理组分间的混合效应与相互作用；与“热力学系统”的区别在于：本节点侧重多组分的具体物性关系。", "includes": ["理想气体混合物的分压、分体积及摩尔分数关系", "湿空气的热力学性质（含湿量、相对湿度、露点、湿球温度）", "液体溶液的相平衡、拉乌尔定律及混合焓/熵计算"], "excludes": ["单一组分纯物质的状态方程与物性图表（归入纯物质、状态方程与物性图表）", "多组分反应体系的化学平衡计算（若涉及化学反应，通常归入化学工程或反应工程，此处仅限物理混合）"], "sibling_distinctions": [{"other_code": "N_6fa0308ea2b93dc2", "rule": "本节点处理多组分混合物（如空气、溶液）的性质；兄弟节点处理单一组分纯物质（如水、氮气）的性质。"}, {"other_code": "N_90a7fd20c30ce5c2", "rule": "本节点提供多组分系统的具体物性计算规则；兄弟节点定义通用的状态参数与过程概念。"}], "cross_boundary_rule": "涉及空气性质时，若将其视为单一理想气体处理，可参考“纯物质”；但在工程热力学中，空气通常作为湿空气（混合物）处理，侧重湿度参数时主挂载至本节点。"}]}
